#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Owner-only steps after `make deploy` (ticket #5): create the GitHub App from
# the stack's setup URL, install it on one private canary repo, and create the
# `ci-runner` org runner group. Re-runnable: each stage checks what's done.

ORG=zeroae
GROUP=ci-runner
STACK="${STACK:-ci-runner}"
PROFILE="${PROFILE:-zeroae-code/AWSPowerUserAccess}"
REGION="${REGION:-us-east-1}"
aws_() { aws --profile "$PROFILE" --region "$REGION" "$@"; }
die() { warn "$1"; exit 1; }

# secret_has FIELD: true when the App secret holds a non-empty FIELD. Never prints it.
secret_has() {
  aws_ secretsmanager get-secret-value --secret-id "$SECRET_ARN" --query SecretString --output text \
    | jq -e --arg f "$1" '.[$f] // empty | tostring | length > 0' >/dev/null
}
secret_field() {  # only for non-secret fields (app_id, app_slug)
  aws_ secretsmanager get-secret-value --secret-id "$SECRET_ARN" --query SecretString --output text | jq -r --arg f "$1" '.[$f]'
}

run_wizard() {

TOTAL_STAGES=5

banner "ci-runner: create the GitHub App and the runner group"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "AWS session and the stack's URLs"
for tool in aws gh jq curl node; do command -v "$tool" >/dev/null || die "$tool is not installed"; done
until aws_ sts get-caller-identity >/dev/null 2>&1; do
  warn "no live AWS session for $PROFILE."
  step "In another terminal: aws sso login --profile $PROFILE --use-device-code"
  pause "Press Enter once you've approved the login"
done
OUTPUTS=$(aws_ cloudformation describe-stacks --stack-name "$STACK" --query 'Stacks[0].Outputs' --output json) \
  || die "stack $STACK not found: run 'make deploy' first"
SETUP_URL=$(jq -r '.[]|select(.OutputKey=="SetupUrl").OutputValue' <<<"$OUTPUTS")
SECRET_ARN=$(jq -r '.[]|select(.OutputKey=="AppSecretArn").OutputValue' <<<"$OUTPUTS")
say "Stack $STACK found."
note "setup URL: $SETUP_URL"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the GitHub App"
if secret_has private_key; then
  say "The secret already holds an App key: skipping (App $(secret_field app_slug), id $(secret_field app_id))."
else
  say "The setup page posts the App manifest to GitHub. You only press one button."
  step "Sign in to GitHub as an owner of the $ORG org, in the browser that opens."
  open_url "$SETUP_URL"
  step "GitHub shows 'Create GitHub App for $ORG'. Leave the name and settings as they are,"
  step "and press 'Create GitHub App'."
  step "You land back on a page saying 'Stored the GitHub App ...'. Don't use its install link yet."
  note "If GitHub says the name is taken: redeploy with  make deploy  after setting the"
  note "stack's AppName parameter, then re-run this wizard."
  pause "Press Enter once you see 'Stored the GitHub App'"
  secret_has private_key || die "the secret still has no key: re-run this wizard and try the page again"
fi
APP_SLUG=$(secret_field app_slug)
APP_ID=$(secret_field app_id)
secret_has webhook_secret || die "the secret has a key but no webhook secret: empty it and start again"
CODE=$(curl -s -o /dev/null -w '%{http_code}' "$SETUP_URL")
[[ "$CODE" == 410 ]] || die "setup URL answered $CODE, expected 410 (refusing): check the setup function"
say "${GREEN}✓${RESET} App $APP_SLUG (id $APP_ID): key and webhook secret are in the stack's secret."
say "${GREEN}✓${RESET} The setup URL now refuses every call (HTTP 410)."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Install the App on one private canary repo"
say "Pick the one private $ORG repo that will run the canary jobs."
while :; do
  ask CI_RUNNER_CANARY_REPO "Canary repo name (without '$ORG/'):"
  VIS=$(gh api "repos/$ORG/$CI_RUNNER_CANARY_REPO" --jq .visibility 2>/dev/null || true)
  [[ "$VIS" == private ]] && break
  warn "$ORG/$CI_RUNNER_CANARY_REPO is ${VIS:-not found}; it must be a private repo."
done
write_env CI_RUNNER_CANARY_REPO "$CI_RUNNER_CANARY_REPO"
open_url "https://github.com/apps/$APP_SLUG/installations/new"
step "Choose the $ORG organization."
step "Select 'Only select repositories', and pick $CI_RUNNER_CANARY_REPO (only that one)."
step "Check the permissions read: Self-hosted runners (org) read & write, Actions read, Checks read & write."
step "Press 'Install'."
pause "Press Enter once it's installed"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Create the '$GROUP' runner group"
say "The runner group needs the admin:org scope on your gh login."
if ! gh api "orgs/$ORG/actions/runner-groups" >/dev/null 2>&1; then
  step "gh will ask you to approve the extra scope in the browser."
  gh auth refresh -h github.com -s admin:org
fi
REPO_ID=$(gh api "repos/$ORG/$CI_RUNNER_CANARY_REPO" --jq .id)
GROUP_ID=$(gh api "orgs/$ORG/actions/runner-groups" --paginate \
  --jq ".runner_groups[]|select(.name==\"$GROUP\").id")
if [[ -z "$GROUP_ID" ]]; then
  printf '\n'
  say "Next: create the org runner group '$GROUP', limited to $CI_RUNNER_CANARY_REPO, public repos off."
  confirm "Create it now? (type y, then Enter)" \
    || die "runner group not created; re-run this wizard and answer y at this prompt"
  GROUP_ID=$(jq -n --argjson r "$REPO_ID" --arg n "$GROUP" \
      '{name:$n, visibility:"selected", selected_repository_ids:[$r], allows_public_repositories:false}' \
    | gh api -X POST "orgs/$ORG/actions/runner-groups" --input - --jq .id)
  say "${GREEN}✓${RESET} created runner group $GROUP (id $GROUP_ID)."
else
  say "Runner group $GROUP exists (id $GROUP_ID): making sure it's selected-only, public off."
  gh api -X PATCH "orgs/$ORG/actions/runner-groups/$GROUP_ID" \
    -f visibility=selected -F allows_public_repositories=false >/dev/null
  gh api -X PUT "orgs/$ORG/actions/runner-groups/$GROUP_ID/repositories/$REPO_ID" >/dev/null
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Verify"
OK=1
G=$(gh api "orgs/$ORG/actions/runner-groups/$GROUP_ID")
if jq -e '.visibility=="selected" and .allows_public_repositories==false' <<<"$G" >/dev/null; then
  say "${GREEN}✓${RESET} group $GROUP: selected repositories, public repos not allowed."
else OK=0; warn "group $GROUP settings are wrong: $(jq -c '{visibility,allows_public_repositories}' <<<"$G")"; fi
GR=$(gh api "orgs/$ORG/actions/runner-groups/$GROUP_ID/repositories" --jq '[.repositories[].name]|join(",")')
[[ "$GR" == "$CI_RUNNER_CANARY_REPO" ]] && say "${GREEN}✓${RESET} group repos: $GR" \
  || { OK=0; warn "group repos are '$GR', expected only $CI_RUNNER_CANARY_REPO"; }
INST=$(gh api "orgs/$ORG/installations" --paginate --jq ".installations[]|select(.app_slug==\"$APP_SLUG\")")
if [[ -z "$INST" ]]; then OK=0; warn "no installation of $APP_SLUG on $ORG found"
else
  INST_ID=$(jq -r .id <<<"$INST")
  # A user token can't list an App installation's repos; ask as the App itself
  # (JWT from the key in the secret, never printed).
  IR=$(aws_ secretsmanager get-secret-value --secret-id "$SECRET_ARN" --query SecretString --output text \
    | INST_ID="$INST_ID" node -e '
      const c = require("crypto"); let s = "";
      process.stdin.on("data", d => s += d).on("end", async () => {
        const x = JSON.parse(s), n = Math.floor(Date.now() / 1000);
        const b = o => Buffer.from(JSON.stringify(o)).toString("base64url");
        const u = b({ alg: "RS256", typ: "JWT" }) + "." + b({ iat: n - 60, exp: n + 540, iss: String(x.app_id) });
        const jwt = u + "." + c.sign("RSA-SHA256", Buffer.from(u), x.private_key).toString("base64url");
        const t = await (await fetch(`https://api.github.com/app/installations/${process.env.INST_ID}/access_tokens`,
          { method: "POST", headers: { Authorization: `Bearer ${jwt}`, Accept: "application/vnd.github+json" } })).json();
        const r = await (await fetch("https://api.github.com/installation/repositories",
          { headers: { Authorization: `token ${t.token}` } })).json();
        console.log(r.repositories.map(x => x.name).join(","));
      });') || IR="?"
  if [[ "$(jq -r .repository_selection <<<"$INST")" == selected && "$IR" == "$CI_RUNNER_CANARY_REPO" ]]; then
    say "${GREEN}✓${RESET} App installed on $ORG, selected repos: $IR"
  else OK=0; warn "App installation covers '$IR' ($(jq -r .repository_selection <<<"$INST")), expected only $CI_RUNNER_CANARY_REPO"; fi
  jq -e '.events|index("workflow_job")' <<<"$INST" >/dev/null \
    && say "${GREEN}✓${RESET} subscribed to workflow_job" || { OK=0; warn "workflow_job event missing"; }
  say "  permissions: $(jq -c .permissions <<<"$INST")"
fi
(( OK )) || SKIPPED+=("fix the warnings in stage 5, then re-run this wizard")
pause

finish
}

run_wizard "$@"; exit
